import { readFileSync, readdirSync } from 'node:fs';
const ROOT='/home/runner/workspace';
// --- what migrations create ---
const sqlFiles=readdirSync(ROOT+'/migrations').filter(f=>f.endsWith('.sql')).sort();
let sql='';
for(const f of sqlFiles) sql+='\n'+readFileSync(ROOT+'/migrations/'+f,'utf8');
const mTables=new Set();
for(const m of sql.matchAll(/CREATE TABLE(?:\s+IF NOT EXISTS)?\s+"?([a-z_0-9]+)"?/gi)) mTables.add(m[1].toLowerCase());
// columns created inside CREATE TABLE bodies + ADD COLUMN
const mCols=new Map(); // table -> Set(col)
const add=(t,c)=>{t=t.toLowerCase();c=c.toLowerCase();if(!mCols.has(t))mCols.set(t,new Set());mCols.get(t).add(c);};
for(const m of sql.matchAll(/CREATE TABLE(?:\s+IF NOT EXISTS)?\s+"?([a-z_0-9]+)"?\s*\(([\s\S]*?)\n\s*\);/gi)){
  const t=m[1]; for(const line of m[2].split('\n')){
    const c=line.trim().match(/^"?([a-z_][a-z_0-9]*)"?\s+[a-z]/i);
    if(c && !/^(primary|unique|constraint|foreign|check)$/i.test(c[1])) add(t,c[1]);
  }
}
for(const m of sql.matchAll(/ALTER TABLE\s+(?:ONLY\s+)?"?([a-z_0-9]+)"?([\s\S]*?);/gi)){
  const t=m[1]; for(const c of m[2].matchAll(/ADD COLUMN(?:\s+IF NOT EXISTS)?\s+"?([a-z_0-9]+)"?/gi)) add(t,c[1]);
}
// --- what schema.ts declares ---
const ts=readFileSync(ROOT+'/shared/schema.ts','utf8');
const sTables=new Map();
for(const m of ts.matchAll(/pgTable\(\s*"([a-z_0-9]+)"\s*,\s*\{([\s\S]*?)\n\}/gi)){
  const t=m[1].toLowerCase(); const cols=new Set();
  for(const c of m[2].matchAll(/\b(?:text|varchar|integer|serial|boolean|timestamp|numeric|decimal|jsonb|json|real|bigint|date|uuid|customType|bytea)\(\s*"([a-z_0-9]+)"/gi)) cols.add(c[1].toLowerCase());
  sTables.set(t,cols);
}
const missingTables=[...sTables.keys()].filter(t=>!mTables.has(t));
console.log('schema.ts tables:',sTables.size,'| migration tables:',mTables.size);
console.log('\n== TABLES declared in schema.ts but created by NO migration ==');
missingTables.forEach(t=>console.log('  -',t,`(${sTables.get(t).size} cols)`));
console.log('\n== COLUMNS missing, on tables migrations DO create ==');
let n=0;
for(const [t,cols] of sTables){ if(missingTables.includes(t)) continue;
  const have=mCols.get(t)??new Set();
  const miss=[...cols].filter(c=>!have.has(c));
  if(miss.length){ console.log(`  ${t}: ${miss.join(', ')}`); n+=miss.length; }
}
console.log('\ntotals -> missing tables:',missingTables.length,' missing columns:',n);

-- Canonical processor-payment completion time. Daily payout summaries must be
-- driven by when money completed, not when an unpaid request was created.

BEGIN;

ALTER TABLE transactions
  ADD COLUMN IF NOT EXISTS completed_at timestamp;


CREATE INDEX IF NOT EXISTS transactions_merchant_completed_at_idx
  ON transactions (merchant_id, completed_at)
  WHERE completed_at IS NOT NULL;

COMMIT;

