import { pgTable, text, serial, decimal, timestamp, boolean, integer, jsonb, uuid, uniqueIndex, index, customType, check } from "drizzle-orm/pg-core";
import { sql } from "drizzle-orm";
import { createInsertSchema } from "drizzle-zod";
import { z } from "zod";
import { planIdSchema } from "./plans";

/**
 * Login identities. One row per person who can sign in, so a merchant on a
 * multi-seat plan has one row per teammate. `email` is globally unique: a login
 * addresses exactly one account, which is what makes seat revocation meaningful.
 */
export const users = pgTable("users", {
  id: serial("id").primaryKey(),
  email: text("email").notNull().unique(),
  password: text("password").notNull(),
  merchantId: integer("merchant_id").references(() => merchants.id),
  role: text("role").notNull().default("member"), // owner, member, admin
  name: text("name"),
  // active = can sign in; invited = has not accepted yet; disabled = seat revoked.
  // Invited and active seats both count against the plan's seat limit.
  status: text("status").notNull().default("active"),
  inviteTokenHash: text("invite_token_hash"),
  inviteExpiresAt: timestamp("invite_expires_at"),
  lastLoginAt: timestamp("last_login_at"),
  resetToken: text("reset_token"),
  resetTokenExpiry: timestamp("reset_token_expiry"),
  createdAt: timestamp("created_at").defaultNow(),
}, (t) => ({
  merchantIdIdx: index("users_merchant_id_idx").on(t.merchantId),
  emailLowerUnique: uniqueIndex("users_email_lower_uq").on(sql`lower(${t.email})`),
  inviteTokenHashUnique: uniqueIndex("users_invite_token_hash_uq")
    .on(t.inviteTokenHash)
    .where(sql`${t.inviteTokenHash} is not null`),
  resetTokenHashUnique: uniqueIndex("users_reset_token_hash_uq")
    .on(t.resetToken)
    .where(sql`${t.resetToken} is not null`),
  roleCheck: check("users_role_check", sql`${t.role} in ('owner', 'member', 'admin')`),
  statusCheck: check("users_status_check", sql`${t.status} in ('active', 'invited', 'disabled')`),
}));

export const USER_ROLES = ["owner", "member", "admin"] as const;
export type UserRole = (typeof USER_ROLES)[number];

export const USER_STATUSES = ["active", "invited", "disabled"] as const;
export type UserStatus = (typeof USER_STATUSES)[number];

/** Seats consumed by a user in this state. Disabled seats are free to reuse. */
export const SEAT_CONSUMING_STATUSES = ["active", "invited"] as const;

export const merchants = pgTable("merchants", {
  id: serial("id").primaryKey(),
  name: text("name").notNull(),
  businessName: text("business_name").notNull(),
  businessType: text("business_type"),
  email: text("email").notNull().unique(),
  phone: text("phone"),
  address: text("address"),
  status: text("status").notNull().default("pending"), // pending, verified, active, inactive
  verificationToken: text("verification_token"),
  passwordHash: text("password_hash"),
  googleId: text("google_id"),
  qrCodeUrl: text("qr_code_url"),
  paymentUrl: text("payment_url"),
  currentProviderRate: decimal("current_provider_rate", { precision: 5, scale: 4 }).default("0.0290"), // Default 2.9%
  ourRate: decimal("our_rate", { precision: 5, scale: 4 }).default("0.0020"), // Our 0.20%

  // Additional business details
  director: text("director"),
  nzbn: text("nzbn"), // New Zealand Business Number
  contactEmail: text("contact_email"),
  contactPhone: text("contact_phone"),
  businessAddress: text("business_address"),
  businessDescription: text("business_description"),
  websiteUrl: text("website_url"),
  estimatedAnnualTurnover: text("estimated_annual_turnover"),

  // Bank account details
  bankName: text("bank_name"),
  bankAccountNumber: text("bank_account_number"),
  bankBranch: text("bank_branch"),
  accountHolderName: text("account_holder_name"),

  // Tax information
  gstNumber: text("gst_number"),

  // Branding customization
  customLogoUrl: text("custom_logo_url"), // Custom merchant logo for customer payment page

  // Payment integration
  windcaveApiKey: text("windcave_api_key"), // Encrypted Windcave API key
  windcaveMerchantId: text("windcave_merchant_id"), // Windcave-assigned merchant ID

  // Theme customization
  themeId: text("theme_id").default("classic"),

  // Email verification
  emailVerified: boolean("email_verified").default(false),

  // Onboarding status
  onboardingCompleted: boolean("onboarding_completed").default(false),

  // GST registration (Trades vertical)
  gstRegistered: boolean("gst_registered").notNull().default(false),
  // Trades quote price presentation: inclusive prices already contain GST;
  // exclusive prices are net prices with GST added on top.
  tradeGstMode: text("trade_gst_mode").notNull().default("inclusive"),

  // Dashboard preferences
  dailyGoal: decimal("daily_goal", { precision: 10, scale: 2 }).default("500.00"), // Daily revenue goal in dollars

  // Page-by-page merchant tutorial. A generation is incremented whenever the
  // merchant restarts the walkthroughs so stale browser tabs cannot overwrite
  // the new run.
  tutorialGeneration: integer("tutorial_generation").notNull().default(1),
  tutorialAutoEnabled: boolean("tutorial_auto_enabled").notNull().default(true),

  // Billing card (stored masked — Windcave will handle live processing when ready)
  billingCardLast4: text("billing_card_last4"),
  billingCardBrand: text("billing_card_brand"), // e.g. Visa, Mastercard
  billingCardExpiry: text("billing_card_expiry"), // MM/YY masked storage only

  // Password reset tokens (persisted in DB)
  resetToken: text("reset_token"),
  resetTokenExpiry: timestamp("reset_token_expiry"),

  // Property management — overdue rent reminder policy (auto-resend)
  rentReminderEnabled: boolean("rent_reminder_enabled").notNull().default(true),
  rentReminderDelayDays: integer("rent_reminder_delay_days").notNull().default(3),     // days after due before first reminder
  rentReminderIntervalDays: integer("rent_reminder_interval_days").notNull().default(3), // days between subsequent reminders
  rentReminderMaxCount: integer("rent_reminder_max_count").notNull().default(3),        // max reminders (0 = unlimited)
  // Trades — own reminder on/off switch so disabling rent reminders does not
  // silently stop trades job-invoice reminders (cadence reuses the rent* days).
  tradeRemindersEnabled: boolean("trade_reminders_enabled").notNull().default(true),

  createdAt: timestamp("created_at").defaultNow(),
  updatedAt: timestamp("updated_at").defaultNow(),
});

export const merchantTutorialProgress = pgTable("merchant_tutorial_progress", {
  id: uuid("id").primaryKey().defaultRandom(),
  merchantId: integer("merchant_id").references(() => merchants.id, { onDelete: "cascade" }).notNull(),
  generation: integer("generation").notNull(),
  pageKey: text("page_key").notNull(),
  status: text("status").notNull(), // started, completed, dismissed
  lastStep: integer("last_step").notNull().default(0),
  startedAt: timestamp("started_at").defaultNow(),
  completedAt: timestamp("completed_at"),
  dismissedAt: timestamp("dismissed_at"),
  updatedAt: timestamp("updated_at").defaultNow(),
}, (t) => ({
  merchantGenerationPageUnique: uniqueIndex("merchant_tutorial_progress_run_page_idx").on(t.merchantId, t.generation, t.pageKey),
  merchantGenerationIdx: index("merchant_tutorial_progress_merchant_generation_idx").on(t.merchantId, t.generation),
}));

export const transactions = pgTable("transactions", {
  id: serial("id").primaryKey(),
  merchantId: integer("merchant_id").references(() => merchants.id),
  taptStoneId: integer("tapt_stone_id").references(() => taptStones.id), // Link to specific tapt stone
  itemName: text("item_name").notNull(),
  price: decimal("price", { precision: 10, scale: 2 }).notNull(),

    sql`${t.receiptShare} is null or (${t.shareIndex} >= 1 and ${t.receiptShare} = ${t.shareIndex})`,
  ),
}));

// Refunds table to track all refund activities
export const refunds = pgTable("refunds", {
  id: serial("id").primaryKey(),
  transactionId: integer("transaction_id").references(() => transactions.id),
  merchantId: integer("merchant_id").references(() => merchants.id),
  refundAmount: decimal("refund_amount", { precision: 10, scale: 2 }).notNull(),
  refundReason: text("refund_reason"),
  refundMethod: text("refund_method").default("original_payment_method"), // original_payment_method, bank_transfer, manual
  status: text("status").notNull().default("pending"), // pending, processing, completed, failed
  windcaveRefundId: text("windcave_refund_id"), // External refund processor ID

  // Fee handling for refunds
  windcaveFeeRefunded: decimal("windcave_fee_refunded", { precision: 10, scale: 2 }).default("0.00"),
  platformFeeRefunded: decimal("platform_fee_refunded", { precision: 10, scale: 2 }).default("0.00"),

  initiatedBy: text("initiated_by"), // merchant, customer, admin
  customerNotified: boolean("customer_notified").default(false),
  completedAt: timestamp("completed_at"),
  createdAt: timestamp("created_at").defaultNow(),
}, (t) => ({
  transactionIdIdx: index("refunds_transaction_id_idx").on(t.transactionId),
  merchantIdIdx: index("refunds_merchant_id_idx").on(t.merchantId),
}));

// Platform settlements - tracks money owed to merchants (Marketplace Model)
export const merchantSettlements = pgTable("merchant_settlements", {
  id: serial("id").primaryKey(),
  merchantId: integer("merchant_id").references(() => merchants.id),
  settlementPeriod: text("settlement_period").notNull(), // e.g., "2025-01-01"
  totalTransactionAmount: decimal("total_transaction_amount", { precision: 10, scale: 2 }).notNull(),
  totalWindcaveFees: decimal("total_windcave_fees", { precision: 10, scale: 2 }).notNull(),
  totalPlatformFees: decimal("total_platform_fees", { precision: 10, scale: 2 }).notNull(),
  netSettlementAmount: decimal("net_settlement_amount", { precision: 10, scale: 2 }).notNull(),
  status: text("status").notNull().default("pending"), // pending, processing, completed, failed
  settlementDate: timestamp("settlement_date"),
  createdAt: timestamp("created_at").defaultNow(),
});

// Platform fees table for tracking revenue collection
export const platformFees = pgTable("platform_fees", {
  id: serial("id").primaryKey(),
  transactionId: integer("transaction_id").references(() => transactions.id),
  merchantId: integer("merchant_id").references(() => merchants.id),
  feeAmount: decimal("fee_amount", { precision: 10, scale: 2 }).notNull(),
  transactionAmount: decimal("transaction_amount", { precision: 10, scale: 2 }).notNull(),
  status: text("status").notNull().default("pending"), // pending, collected, failed
  collectedAt: timestamp("collected_at"),
  createdAt: timestamp("created_at").defaultNow(),
});

// Split payments schemas
export const insertSplitPaymentSchema = createInsertSchema(splitPayments).omit({
  id: true,
  createdAt: true,
  paidAt: true,
});

export const createSplitPaymentSchema = z.object({
  transactionId: z.number().min(1, "Transaction ID is required"),
  splitIndex: z.number().min(1, "Split index is required"),
  amount: z.string().refine((val) => {
    const num = parseFloat(val);
    return !isNaN(num) && num > 0;
  }, "Amount must be a positive number"),
  paymentMethod: z.enum(["qr_code", "nfc_tap", "card_reader", "manual", "cash", "tap_to_pay", "api"]).default("qr_code"),
});

// Bill split creation schema
export const createBillSplitSchema = z.object({
  transactionId: z.number().min(1, "Transaction ID is required"),
  totalSplits: z.number().min(2, "Must have at least 2 splits").max(10, "Maximum 10 splits allowed"),
});

// Add refund schemas only - keeping existing schemas intact
export const insertRefundSchema = createInsertSchema(refunds).omit({
  id: true,

}, (t) => ({
  nextRunDateIdx: index("active_schedules_next_run_date_idx").on(t.nextRunDate),
  merchantStatusIdx: index("active_schedules_merchant_status_idx").on(t.merchantId, t.status),
}));

export const invoicesRentRequests = pgTable("invoices_rent_requests", {
  id: uuid("id").primaryKey().defaultRandom(),
  merchantId: integer("merchant_id").references(() => merchants.id).notNull(),
  tenantProfileId: uuid("tenant_profile_id").references(() => tenantProfiles.id).notNull(),
  scheduleId: uuid("schedule_id").references(() => activeSchedules.id),
  amountCents: integer("amount_cents").notNull(),
  token: text("token").notNull().unique(),
  deliveryChannel: text("delivery_channel").notNull(),
  billingPeriodStart: timestamp("billing_period_start"),
  // What this invoice is for. "rent" is the default (recurring or one-off rent);
  // "charge" is a one-off non-rent bill (utilities, late fee, cleaning, damages, other).
  // chargeType carries the category, description the human-readable label shown to the tenant.
  kind: text("kind").notNull().default("rent"),
  chargeType: text("charge_type"),
  description: text("description"),
  // Optional supporting document (PDF/image) attached to a one-off charge. Shown
  // to the tenant on the checkout page as a "View invoice" link they can open,
  // download or share. Null for rent and for charges sent without an attachment.
  documentUrl: text("document_url"),
  documentName: text("document_name"),
  status: text("status").notNull().default("pending_dispatch"),
  dueAt: timestamp("due_at").notNull(),
  dispatchedAt: timestamp("dispatched_at"),
  sentAt: timestamp("sent_at"),
  paidAt: timestamp("paid_at"),
  voidedAt: timestamp("voided_at"),
  externalPaymentReference: text("external_payment_reference"),
  lastReminderSentAt: timestamp("last_reminder_sent_at"),
  reminderCount: integer("reminder_count").notNull().default(0),
  windcaveSessionId: text("windcave_session_id"),
  windcaveTransactionId: text("windcave_transaction_id"),
  // Split-bill: the merchant enables it; the tenant chooses how many flatmates
  // share the rent on the checkout page. Each share is paid via the same link.
  splitEnabled: boolean("split_enabled").notNull().default(false),
  splitCount: integer("split_count"),                       // chosen number of ways (null until tenant splits)
  splitPaidCount: integer("split_paid_count").notNull().default(0),
  splitPaidSessions: text("split_paid_sessions").array(),   // Windcave session ids already counted (idempotency)
  splitPayerEmails: text("split_payer_emails").array(),     // emails collected from share payers (for GST copies)
