1	/**
2	 * SQL migration runner.
3	 *
4	 * Why this exists
5	 * ---------------
6	 * The `migrations/*.sql` files were checked in but nothing ever applied them:
7	 * `drizzle.__drizzle_migrations` was empty, the startup `drizzle-kit push` is
8	 * opt-in behind `RUN_SCHEMA_PUSH`/`RUN_MIGRATIONS`, and everything else was
9	 * applied by hand. That let the dev database fall three migrations behind
10	 * `shared/schema.ts`, and because Drizzle's `select()` enumerates every column
11	 * declared in the schema, a single missing column ("billing_claim_token") took
12	 * the whole app down after login.
13	 *
14	 * This runner makes "which migrations has this database actually seen?" a
15	 * recorded fact instead of folklore.
16	 *
17	 * Design decisions
18	 * ----------------
19	 * 1. `pg` (not `@neondatabase/serverless`). DDL needs a real session-scoped
20	 *    connection with honest transaction semantics.
21	 *
22	 * 2. Ordering is plain lexical (UTF-16 code unit) order, never `localeCompare`
23	 *    — ICU collation treats `_` as variable-weight punctuation and can reorder
24	 *    `0010_...` vs `0010a_...`. `_` is 0x5F and `a` is 0x61, so `0010_` sorts
25	 *    before `0010a_`, which is exactly the order `0010a` documents it needs
26	 *    (it must run before `0011`). `assertLexicalMigrationOrder` asserts this
27	 *    rather than trusting it: every filename must carry a 4-digit zero-padded
28	 *    prefix with an optional lowercase letter suffix, and lexical order must
29	 *    agree with (numeric prefix, letter suffix) order.
30	 *
31	 * 3. Embedded BEGIN/COMMIT: the migration files are inconsistent — 0000-0006
32	 *    have no transaction control, 0007-0013 wrap themselves in `BEGIN;`/
33	 *    `COMMIT;`. Running them as-is would mean the ledger INSERT could not share
34	 *    a transaction with the migration (the file would already have committed),
35	 *    so a crash between the two would leave an applied-but-unrecorded
36	 *    migration. Wrapping them as-is instead produces nested-transaction
37	 *    warnings and a file that self-commits halfway through the outer
38	 *    transaction.
39	 *
40	 *    So: we parse each file into top-level statements with a scanner that
41	 *    understands line/block comments, single- and double-quoted literals and
42	 *    dollar-quoted bodies (`$$ ... $$`, so `DO $$ BEGIN ... END $$;` stays one
43	 *    statement and its inner BEGIN/END is never mistaken for transaction
44	 *    control), drop the top-level transaction-control statements, and run the
45	 *    remainder plus the ledger INSERT inside one transaction we own. Migration
46	 *    applied <=> ledger row present, atomically. This is behaviour-preserving
47	 *    for the current files: every self-transacting migration is wholly wrapped,
48	 *    with no statements before BEGIN or after COMMIT.
49	 *
50	 * 4. The ledger lives in the `drizzle` schema, not `public`. `drizzle-kit push`
51	 *    diffs `public` against `shared/schema.ts` and would offer to DROP an
52	 *    unknown `public` table; the `drizzle` schema is already outside its view.
53	 *
54	 * 5. `--baseline` records migrations as applied WITHOUT executing them, for
55	 *    adopting this runner on a database that already has their effects. It is
56	 *    deliberately awkward to trigger: it needs a second `--confirm` flag, it
57	 *    refuses on a database whose `public` schema has no tables (baselining an
58	 *    empty database would permanently skip the entire schema), and it refuses
59	 *    if the ledger already has rows unless `--force`.
60	 *
61	 * Usage
62	 * -----
63	 *   npm run db:migrate                          apply pending migrations
64	 *   npm run db:migrate:status                   report only, touches nothing
65	 *   npm run db:migrate -- --dry-run             list what would be applied
66	 *   npm run db:migrate:baseline                 print the baseline plan, refuse
67	 *   npm run db:migrate:baseline -- --confirm    record as applied, run nothing
68	 */
69	
70	import crypto from "crypto";
71	import fs from "fs";
72	import path from "path";
73	import { findMissingBaselineEffects } from "./migration-baseline-contract";
74	
75	// ---------------------------------------------------------------------------
76	// Configuration
77	// ---------------------------------------------------------------------------
78	
79	/** Schema holding the ledger. Outside `public` so `drizzle-kit push` ignores it. */
80	export const LEDGER_SCHEMA = "drizzle";
81	export const LEDGER_TABLE = "applied_migrations";
82	export const LEDGER_QUALIFIED = `${LEDGER_SCHEMA}.${LEDGER_TABLE}`;
83	
84	/** Repo-relative directory holding the checked-in `*.sql` migrations. */
85	export const MIGRATIONS_DIRNAME = "migrations";
86	
87	export function defaultMigrationsDir(): string {
88	  return path.resolve(process.cwd(), MIGRATIONS_DIRNAME);
89	}
90	
91	// ---------------------------------------------------------------------------
92	// Minimal client interface (so tests can inject a fake; no live DB required)
93	// ---------------------------------------------------------------------------
94	
95	export interface QueryResultLike<Row = any> {
96	  rows: Row[];
97	}
98	
99	export interface MigrationClient {
100	  query<Row = any>(
101	    text: string,
102	    values?: unknown[],
103	  ): Promise<QueryResultLike<Row>>;
104	}
105	
106	// ---------------------------------------------------------------------------
107	// Filenames and ordering
108	// ---------------------------------------------------------------------------
109	
110	/**
111	 * `0013_subscription_plans.sql` -> { numeric: 13, letter: "", rest: "..." }
112	 * `0010a_reconcile...sql`       -> { numeric: 10, letter: "a", rest: "..." }
113	 */
114	const MIGRATION_NAME_PATTERN = /^(\d{4})([a-z]*)_([^/\\]*)\.sql$/;
115	
116	export interface ParsedMigrationName {
117	  filename: string;
118	  numeric: number;
119	  letter: string;
120	  rest: string;
121	}
122	
123	export function parseMigrationName(filename: string): ParsedMigrationName | null {
124	  const match = MIGRATION_NAME_PATTERN.exec(filename);
125	  if (!match) return null;
126	  return {
127	    filename,
128	    numeric: Number.parseInt(match[1], 10),
129	    letter: match[2],
130	    rest: match[3],
131	  };
132	}
133	
134	/**
135	 * Sort by UTF-16 code unit, explicitly NOT `localeCompare`: locale collation
136	 * can treat `_` as ignorable punctuation and flip `0010_x` / `0010a_y`.
137	 */
138	export function sortMigrationFiles(filenames: readonly string[]): string[] {
139	  return [...filenames].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
140	}
141	
142	/**
143	 * Assert that lexical order is a safe apply order, instead of assuming it.
144	 *
145	 * Catches the two ways a future filename could silently reorder the run:
146	 * a non-conforming name (`10_foo.sql`, `0010A_foo.sql`, `0010a-foo.sql`), or a
147	 * name whose lexical position disagrees with its numeric position.
148	 */
149	export function assertLexicalMigrationOrder(filenames: readonly string[]): string[] {
150	  const lexical = sortMigrationFiles(filenames);
151	
152	  const parsed: ParsedMigrationName[] = [];
153	  const malformed: string[] = [];
154	  for (const filename of lexical) {
155	    const entry = parseMigrationName(filename);
156	    if (entry) parsed.push(entry);
157	    else malformed.push(filename);
158	  }
159	
160	  if (malformed.length > 0) {
161	    throw new Error(
162	      `Migration filenames must look like 0000_name.sql (4-digit zero-padded ` +
163	        `prefix, optional lowercase letter suffix, then "_"). Offending: ` +
164	        `${malformed.join(", ")}. Lexical apply order cannot be trusted until ` +
165	        `they are renamed.`,
166	    );
167	  }
168	
169	  const semantic = [...parsed].sort((a, b) => {
170	    if (a.numeric !== b.numeric) return a.numeric - b.numeric;
171	    if (a.letter !== b.letter) return a.letter < b.letter ? -1 : 1;
172	    return a.rest < b.rest ? -1 : a.rest > b.rest ? 1 : 0;
173	  });
174	
175	  for (let i = 0; i < semantic.length; i += 1) {
176	    if (semantic[i].filename !== lexical[i]) {
177	      throw new Error(
178	        `Migration ordering is ambiguous: lexical order and numeric order ` +
179	          `disagree at position ${i} (lexical="${lexical[i]}", ` +
180	          `numeric="${semantic[i].filename}"). Rename the migrations so both ` +
181	          `agree before running them.`,
182	      );
183	    }
184	  }
185	
186	  return lexical;
187	}
188	
189	/** Read `migrations/*.sql`, ordered, with the ordering invariant asserted. */
190	export function listMigrationFiles(dir: string = defaultMigrationsDir()): string[] {
191	  let entries: string[];
192	  try {
193	    entries = fs.readdirSync(dir);
194	  } catch (error) {
195	    throw new Error(
196	      `Cannot read migrations directory ${dir}: ${(error as Error).message}`,
197	    );
198	  }
199	  const sqlFiles = entries.filter((name) => name.endsWith(".sql"));
200	  return assertLexicalMigrationOrder(sqlFiles);
201	}
202	
203	// ---------------------------------------------------------------------------
204	// Checksums
205	// ---------------------------------------------------------------------------
206	
207	/**
208	 * SHA-256 over the migration text, normalised for a UTF-8 BOM and CRLF line
209	 * endings so a Windows checkout does not raise false drift. This means the
210	 * value will not match a bare `sha256sum` of a CRLF copy of the file — that is
211	 * the intended trade: false drift alarms are worse than shell-comparability.
212	 */
213	export function checksumMigrationSource(source: string): string {
214	  const normalised = source.replace(/^\uFEFF/, "").replace(/\r\n/g, "\n");
215	  return crypto.createHash("sha256").update(normalised, "utf8").digest("hex");
216	}
217	
218	export function readMigrationSource(dir: string, filename: string): string {
219	  return fs.readFileSync(path.join(dir, filename), "utf8");
220	}
221	
222	export function checksumMigrationFile(dir: string, filename: string): string {
223	  return checksumMigrationSource(readMigrationSource(dir, filename));
224	}
225	
226	// ---------------------------------------------------------------------------
227	// SQL scanning: split into top-level statements, drop transaction control
228	// ---------------------------------------------------------------------------
229	
230	export interface SqlChunk {
231	  /** Exact source slice. Chunks are contiguous and cover the whole input. */
232	  raw: string;
233	  /** Comment-stripped, whitespace-collapsed, upper-cased, no trailing `;`. */
234	  normalized: string;
235	  /** Only whitespace and/or comments. */
236	  isEmpty: boolean;
237	  /** A top-level BEGIN/COMMIT/ROLLBACK/... that we must not send ourselves. */
238	  isTransactionControl: boolean;
239	  startOffset: number;
240	  /** 1-based line number of the chunk start, for error messages. */
241	  line: number;
242	}
243	
244	function isIdentStart(ch: string | undefined): boolean {
245	  return !!ch && /[A-Za-z_\u0080-\uffff]/.test(ch);
246	}
247	
248	function isIdentPart(ch: string | undefined): boolean {
249	  return !!ch && /[A-Za-z0-9_\u0080-\uffff]/.test(ch);
250	}
251	
252	/**
253	 * If a dollar-quote tag opens at `i`, return the tag (`$$`, `$body$`, ...).
254	 * `$1` and `$` followed by anything else are not dollar quotes.
255	 */
256	function matchDollarTag(sql: string, i: number): string | null {
257	  if (sql[i] !== "$") return null;
258	  let j = i + 1;
259	  if (sql[j] === "$") return sql.slice(i, j + 1);
260	  if (!isIdentStart(sql[j])) return null;
261	  j += 1;
262	  while (isIdentPart(sql[j])) j += 1;
263	  if (sql[j] !== "$") return null;
264	  return sql.slice(i, j + 1);
265	}
266	
267	/** Index just past a single-quoted literal starting at `i`. */
268	function skipSingleQuoted(sql: string, i: number, escapeString: boolean): number {
269	  let j = i + 1;
270	  while (j < sql.length) {
271	    const ch = sql[j];
272	    if (escapeString && ch === "\\") {
273	      j += 2;
274	      continue;
275	    }
276	    if (ch === "'") {
277	      if (sql[j + 1] === "'") {
278	        j += 2;
279	        continue;
280	      }
281	      return j + 1;
282	    }
283	    j += 1;
284	  }
285	  return sql.length;
286	}
287	
288	/** Index just past a double-quoted identifier starting at `i`. */
289	function skipDoubleQuoted(sql: string, i: number): number {
290	  let j = i + 1;
291	  while (j < sql.length) {
292	    if (sql[j] === '"') {
293	      if (sql[j + 1] === '"') {
294	        j += 2;
295	        continue;
296	      }
297	      return j + 1;
298	    }
299	    j += 1;
300	  }
301	  return sql.length;
302	}
303	
304	/** Index just past a `-- ...` comment (newline included). */
305	function skipLineComment(sql: string, i: number): number {
306	  const newline = sql.indexOf("\n", i);
307	  return newline === -1 ? sql.length : newline + 1;
308	}
309	
310	// Index just past a slash-star block comment. Postgres nests these, so track depth.
311	function skipBlockComment(sql: string, i: number): number {
312	  let depth = 0;
313	  let j = i;
314	  while (j < sql.length) {
315	    if (sql[j] === "/" && sql[j + 1] === "*") {
316	      depth += 1;
317	      j += 2;
318	      continue;
319	    }
320	    if (sql[j] === "*" && sql[j + 1] === "/") {
321	      depth -= 1;
322	      j += 2;
323	      if (depth === 0) return j;
324	      continue;
325	    }
326	    j += 1;
327	  }
328	  return sql.length;
329	}
330	
331	/** True when the `'` at `i` opens an `E'...'` backslash-escape string. */
332	function isEscapeStringStart(sql: string, i: number): boolean {
333	  const prev = sql[i - 1];
334	  if (prev !== "E" && prev !== "e") return false;
335	  return !isIdentPart(sql[i - 2]);
336	}
337	
338	/**
339	 * Remove comments while preserving string and dollar-quoted content, so a
340	 * statement can be classified without corrupting anything we will execute.
341	 * The result is used ONLY for classification — execution always uses `raw`.
342	 */
343	export function stripSqlComments(sql: string): string {
344	  let out = "";
345	  let i = 0;
346	  while (i < sql.length) {
347	    const ch = sql[i];
348	    if (ch === "-" && sql[i + 1] === "-") {
349	      const end = skipLineComment(sql, i);
350	      out += "\n";
351	      i = end;
352	      continue;
353	    }
354	    if (ch === "/" && sql[i + 1] === "*") {
355	      const end = skipBlockComment(sql, i);
356	      out += " ";
357	      i = end;
358	      continue;
359	    }
360	    if (ch === "'") {
361	      const end = skipSingleQuoted(sql, i, isEscapeStringStart(sql, i));
362	      out += sql.slice(i, end);
363	      i = end;
364	      continue;
365	    }
366	    if (ch === '"') {
367	      const end = skipDoubleQuoted(sql, i);
368	      out += sql.slice(i, end);
369	      i = end;
370	      continue;
371	    }
372	    const tag = matchDollarTag(sql, i);
373	    if (tag) {
374	      const close = sql.indexOf(tag, i + tag.length);
375	      const end = close === -1 ? sql.length : close + tag.length;
376	      out += sql.slice(i, end);
377	      i = end;
378	      continue;
379	    }
380	    out += ch;
381	    i += 1;
382	  }
383	  return out;
384	}
385	
386	function normalizeStatement(raw: string): string {
387	  return stripSqlComments(raw)
388	    .replace(/\s+/g, " ")
389	    .trim()
390	    .replace(/;+$/, "")
391	    .trim()
392	    .toUpperCase();
393	}
394	
395	/**
396	 * Transaction-control statements we must strip because we supply our own
397	 * transaction. Deliberately does NOT match SAVEPOINT / RELEASE SAVEPOINT /
398	 * ROLLBACK TO SAVEPOINT, which are legal inside our transaction and must
399	 * survive.
400	 */
401	export function isTransactionControlStatement(normalized: string): boolean {
402	  if (/^(?:BEGIN|START TRANSACTION|COMMIT|END|ROLLBACK|ABORT)$/.test(normalized)) {
403	    return true;
404	  }
405	  if (/^(?:BEGIN|COMMIT|END|ROLLBACK|ABORT) (?:WORK|TRANSACTION)$/.test(normalized)) {
406	    return true;
407	  }
408	  if (
409	    /^(?:BEGIN(?: WORK| TRANSACTION)?|START TRANSACTION) (?:ISOLATION LEVEL |READ ONLY|READ WRITE|DEFERRABLE|NOT DEFERRABLE)/.test(
410	      normalized,
411	    )
412	  ) {
413	    return true;
414	  }
415	  if (
416	    /^(?:COMMIT|END|ROLLBACK)(?: WORK| TRANSACTION)? AND (?:NO )?CHAIN$/.test(normalized)
417	  ) {
418	    return true;
419	  }
420	  return false;
421	}
422	
423	/**
424	 * Split SQL into top-level statements. Understands `--` and nested block
425	 * comments, `'...'` (incl. `E'...'`), `"..."` and `$tag$...$tag$`, so
426	 * semicolons inside a `DO $$ ... $$` body never split a statement.
427	 *
428	 * The returned chunks are contiguous and lossless: joining every `raw`
429	 * reproduces the input byte for byte.
430	 */
431	export function splitSqlStatements(sql: string): SqlChunk[] {
432	  const chunks: SqlChunk[] = [];
433	  let start = 0;
434	  let i = 0;
435	
436	  const push = (from: number, to: number) => {
437	    const raw = sql.slice(from, to);
438	    const normalized = normalizeStatement(raw);
439	    chunks.push({
440	      raw,
441	      normalized,
442	      isEmpty: normalized === "",
443	      isTransactionControl:
444	        normalized !== "" && isTransactionControlStatement(normalized),
445	      startOffset: from,
446	      line: sql.slice(0, from).split("\n").length,
447	    });
448	  };
449	
450	  while (i < sql.length) {
451	    const ch = sql[i];
452	    if (ch === "-" && sql[i + 1] === "-") {
453	      i = skipLineComment(sql, i);
454	      continue;
455	    }
456	    if (ch === "/" && sql[i + 1] === "*") {
457	      i = skipBlockComment(sql, i);
458	      continue;
459	    }
460	    if (ch === "'") {
461	      i = skipSingleQuoted(sql, i, isEscapeStringStart(sql, i));
462	      continue;
463	    }
464	    if (ch === '"') {
465	      i = skipDoubleQuoted(sql, i);
466	      continue;
467	    }
468	    const tag = matchDollarTag(sql, i);
469	    if (tag) {
470	      const close = sql.indexOf(tag, i + tag.length);
471	      i = close === -1 ? sql.length : close + tag.length;
472	      continue;
473	    }
474	    if (ch === ";") {
475	      push(start, i + 1);
476	      i += 1;
477	      start = i;
478	      continue;
479	    }
480	    i += 1;
481	  }
482	
483	  if (start < sql.length) push(start, sql.length);
484	  return chunks;
485	}
486	
487	/** Executable statements only: comments/whitespace and transaction control removed. */
488	export function executableStatements(sql: string): SqlChunk[] {
489	  return splitSqlStatements(sql).filter(
490	    (chunk) => !chunk.isEmpty && !chunk.isTransactionControl,
491	  );
492	}
493	
494	// ---------------------------------------------------------------------------
495	// Planning: compare files on disk against the ledger
496	// ---------------------------------------------------------------------------
497	
498	export interface LedgerRow {
499	  filename: string;
500	  checksum: string;
501	  applied_at?: Date | string | null;
502	  baselined?: boolean | null;
503	}
504	
505	export interface DriftRecord {
506	  filename: string;
507	  recordedChecksum: string;
508	  actualChecksum: string;
509	  appliedAt?: Date | string | null;
510	}
511	
512	export interface MigrationPlan {
513	  /** Every `*.sql` on disk, in apply order. */
514	  ordered: string[];
515	  /** Recorded and unchanged since. */
516	  applied: string[];
517	  /** On disk, never recorded — these are what a run would execute. */
518	  pending: string[];
519	  /** Recorded, but the file changed since. Fatal. */
520	  drifted: DriftRecord[];
521	  /** Recorded, but the file is gone from disk. Warning. */
522	  orphaned: string[];
523	  /** Pending files that sort before something already applied. Warning. */
524	  outOfOrder: string[];
525	}
526	
527	export function planMigrations(
528	  ordered: readonly string[],
529	  checksums: ReadonlyMap<string, string>,
530	  ledger: readonly LedgerRow[],
531	): MigrationPlan {
532	  const recorded = new Map<string, LedgerRow>();
533	  for (const row of ledger) recorded.set(row.filename, row);
534	
535	  const applied: string[] = [];
536	  const pending: string[] = [];
537	  const drifted: DriftRecord[] = [];
538	
539	  for (const filename of ordered) {
540	    const row = recorded.get(filename);
541	    if (!row) {
542	      pending.push(filename);
543	      continue;
544	    }
545	    const actual = checksums.get(filename);
546	    if (actual !== undefined && actual !== row.checksum) {
547	      drifted.push({
548	        filename,
549	        recordedChecksum: row.checksum,
550	        actualChecksum: actual,
551	        appliedAt: row.applied_at ?? null,
552	      });
553	      continue;
554	    }
555	    applied.push(filename);
556	  }
557	
558	  const onDisk = new Set(ordered);
559	  const orphaned = ledger
560	    .map((row) => row.filename)
561	    .filter((filename) => !onDisk.has(filename));
562	
563	  const lastApplied = [...applied, ...drifted.map((d) => d.filename)].sort((a, b) =>
564	    a < b ? -1 : a > b ? 1 : 0,
565	  ).pop();
566	  const outOfOrder =
567	    lastApplied === undefined
568	      ? []
569	      : pending.filter((filename) => filename < lastApplied);
570	
571	  return {
572	    ordered: [...ordered],
573	    applied,
574	    pending,
575	    drifted,
576	    orphaned: sortMigrationFiles(orphaned),
577	    outOfOrder,
578	  };
579	}
