581	/** Read every migration's checksum from disk. */
582	export function checksumAll(
583	  dir: string,
584	  filenames: readonly string[],
585	): Map<string, string> {
586	  const map = new Map<string, string>();
587	  for (const filename of filenames) {
588	    map.set(filename, checksumMigrationFile(dir, filename));
589	  }
590	  return map;
591	}
