593	export function describeDrift(drifted: readonly DriftRecord[]): string {
594	  return drifted
595	    .map(
596	      (d) =>
597	        `  • ${d.filename}\n` +
598	        `      recorded checksum : ${d.recordedChecksum}\n` +
599	        `      file checksum now : ${d.actualChecksum}\n` +
600	        `      recorded at       : ${d.appliedAt ?? "unknown"}`,
601	    )
602	    .join("\n");
603	}
