709	export class MigrationExecutionError extends Error {
710	  readonly filename: string;
711	
712	  constructor(filename: string, statementLine: number, cause: unknown) {
713	    const detail = cause instanceof Error ? cause.message : String(cause);
714	    super(
715	      `Migration ${filename} failed at the statement starting on line ` +
716	        `${statementLine}: ${detail}. The transaction was rolled back — this ` +
717	        `migration is NOT applied and NOT recorded.`,
718	    );
719	    this.name = "MigrationExecutionError";
720	    this.filename = filename;
721	    (this as { cause?: unknown }).cause = cause;
722	  }
