757	export interface RunResult {
758	  plan: MigrationPlan;
759	  appliedNow: string[];
760	}
761	
762	export interface RunOptions {
763	  dir?: string;
764	  dryRun?: boolean;
765	  log?: (message: string) => void;
766	}
