1018	// ---------------------------------------------------------------------------
1019	// Startup check — read-only, non-fatal, cannot crash the server
1020	// ---------------------------------------------------------------------------
1021	
1022	export interface StartupCheckOptions {
1023	  dir?: string;
1024	  connectionString?: string;
1025	  log?: (message: string) => void;
1026	  connectionTimeoutMs?: number;
1027	  failOnIssues?: boolean;
1028	}
1029	
1030	/**
1031	 * Log loudly when migrations are pending or drifted. Never applies anything,
1032	 * never throws, never creates the ledger (a read-only check has no schema side
1033	 * effects), and swallows every failure mode including an unreachable database.
1034	 */
1035	export async function reportPendingMigrations(
1036	  options: StartupCheckOptions = {},
1037	): Promise<void> {
1038	  const log = options.log ?? ((message: string) => console.warn(message));
1039	  const failOnIssues = options.failOnIssues ?? false;
1040	  try {
1041	    const connectionString = options.connectionString ?? process.env.DATABASE_URL;
1042	    if (!connectionString) {
1043	      if (failOnIssues) throw new MigrationHistoryError("DATABASE_URL is not set");
1044	      return;
1045	    }
1046	
1047	    const dir = options.dir ?? defaultMigrationsDir();
1048	    if (!fs.existsSync(dir)) {
1049	      if (failOnIssues) throw new MigrationHistoryError(`Migrations directory not found: ${dir}`);
1050	      return;
1051	    }
1052	
1053	    let ordered: string[];
1054	    let checksums: Map<string, string>;
1055	    try {
1056	      ordered = listMigrationFiles(dir);
1057	      checksums = checksumAll(dir, ordered);
1058	    } catch (error) {
1059	      if (failOnIssues) throw error;
1060	      log(`⚠️  Migration check skipped: ${(error as Error).message}`);
1061	      return;
1062	    }
1063	    if (ordered.length === 0) {
1064	      if (failOnIssues) throw new MigrationHistoryError("No migration files found");
1065	      return;
1066	    }
1067	
1068	    // Imported lazily so a missing/broken `pg` install can never block boot.
1069	    const pg = await import("pg");
1070	    const ClientCtor = (pg as any).default?.Client ?? (pg as any).Client;
1071	    const client = new ClientCtor({
1072	      connectionString,
1073	      connectionTimeoutMillis: options.connectionTimeoutMs ?? 5_000,
1074	      statement_timeout: 5_000,
1075	      query_timeout: 5_000,
1076	      application_name: "taptpay-migration-check",
1077	    });
1078	    // A pg Client emits 'error' asynchronously; unhandled, that takes the
1079	    // process down. Absorb it here.
1080	    client.on("error", () => undefined);
1081	
1082	    try {
1083	      await client.connect();
1084	      const ledger = await readMigrationLedgerIfPresent(client as MigrationClient);
1085	      if (ledger === null) {
1086	        log(RULE);
1087	        log(
1088	          `⚠️  MIGRATION LEDGER NOT INITIALISED — ${LEDGER_QUALIFIED} does not ` +
1089	            `exist, so this database has no record of which of the ` +
1090	            `${ordered.length} checked-in migration(s) it has seen.`,
1091	        );
1092	        log(
1093	          `   If this database already has their effects:  npm run db:migrate:baseline -- --confirm`,
1094	        );
1095	        log(`   Otherwise:                                   npm run db:migrate`);
1096	        log(RULE);
1097	        if (failOnIssues) {
1098	          throw new MigrationHistoryError(`Migration ledger ${LEDGER_QUALIFIED} is not initialised`);
1099	        }
1100	        return;
1101	      }
1102	
1103	      const plan = planMigrations(ordered, checksums, ledger);
1104	      const lines = formatPendingReport(plan);
1105	      if (lines.length === 0) {
1106	        console.log(
1107	          `✅ Migrations: all ${plan.applied.length} applied (${LEDGER_QUALIFIED})`,
1108	        );
1109	        return;
1110	      }
1111	      for (const line of lines) log(line);
1112	      if (failOnIssues && (
1113	        plan.drifted.length > 0 || plan.pending.length > 0 ||
1114	        plan.orphaned.length > 0 || plan.outOfOrder.length > 0
1115	      )) {
1116	        throw new MigrationHistoryError(
1117	          `Database migration gate failed: ${plan.pending.length} pending, ${plan.drifted.length} drifted, ${plan.orphaned.length} orphaned, ${plan.outOfOrder.length} out of order`,
1118	        );
1119	      }
1120	    } finally {
1121	      try {
1122	        await client.end();
1123	      } catch {
1124	        // Closing a never-opened or already-broken connection is not a problem.
1125	      }
1126	    }
1127	  } catch (error) {
1128	    // Never fatal: a migration check must not be able to stop the server.
1129	    log(`⚠️  Migration check failed (non-fatal): ${(error as Error).message}`);
1130	    if (failOnIssues) throw error;
1131	  }
1132	}
