/**
 * Rebuildability gate for Step 5.
 *
 * Builds a throwaway database on the same server as DATABASE_URL, applies
 * migrations/*.sql to it with the app's own runner (so the embedded
 * BEGIN;/COMMIT; is handled exactly as production handles it — each file on its
 * own, transaction control stripped), then diffs the resulting database against
 * shared/schema.ts via information_schema. Drops the scratch DB and proves it.
 *
 * It never connects to heliumdb or NEON_DATABASE_URL for anything but the
 * CREATE DATABASE / DROP DATABASE commands, which are issued against the
 * `postgres` maintenance database.
 */
import crypto from "crypto";
import pg from "pg";
import { is } from "drizzle-orm";
import { PgTable, getTableConfig } from "drizzle-orm/pg-core";
import { runPendingMigrations, type MigrationClient } from "../../../../../home/runner/workspace/server/migrate";
import * as schema from "../../../../../home/runner/workspace/shared/schema";

const MIGRATIONS_DIR = "/home/runner/workspace/migrations";

function maintenanceUrl(): { url: string; scratchUrl: (db: string) => string } {
  const raw = process.env.DATABASE_URL;
  if (!raw) throw new Error("DATABASE_URL is not set");
  const parsed = new URL(raw);
  if (parsed.pathname.replace(/^\//, "") === "postgres") {
    throw new Error("Refusing to run: DATABASE_URL already points at `postgres`");
  }
  const maintenance = new URL(raw);
  maintenance.pathname = "/postgres";
  return {
    url: maintenance.toString(),
    scratchUrl: (db: string) => {
      const u = new URL(raw);
      u.pathname = `/${db}`;
      return u.toString();
    },
  };
}

// --- expected shape, straight out of the Drizzle declarations ----------------

interface ExpectedColumn {
  name: string;
  sqlType: string;
  notNull: boolean;
  isPrimaryKey: boolean;
}

function expectedTables(): Map<string, Map<string, ExpectedColumn>> {
  const out = new Map<string, Map<string, ExpectedColumn>>();
  for (const value of Object.values(schema)) {
    if (!is(value, PgTable)) continue;
    const config = getTableConfig(value as any);
    const cols = new Map<string, ExpectedColumn>();
    for (const column of config.columns) {
      cols.set(column.name, {
        name: column.name,
        sqlType: column.getSQLType(),
        notNull: column.notNull,
        isPrimaryKey: column.primary,
      });
    }
    out.set(config.name, cols);
  }
  return out;
}

/**
 * Normalise a Drizzle SQL type and an information_schema type onto the same
 * vocabulary so they can be compared. `serial` is `integer` once it is in the
 * catalogue; a primary key is NOT NULL whether or not the declaration says so.
 */
function normaliseType(raw: string): string {
  let t = raw.trim().toLowerCase().replace(/\s+/g, " ");
  t = t.replace(/\( *(\d+) *, *(\d+) *\)/, "($1,$2)").replace(/\( *(\d+) *\)/, "($1)");
  if (t === "serial" || t === "bigserial" || t === "smallserial") {
    return t === "serial" ? "integer" : t === "bigserial" ? "bigint" : "smallint";
  }
  if (t === "timestamp") return "timestamp without time zone";
  if (t === "timestamptz") return "timestamp with time zone";
  if (t === "double precision") return "double precision";
  if (/^varchar/.test(t)) return t.replace(/^varchar/, "character varying");
  if (t === "numeric") return "numeric";
  return t;
}

// --- actual shape, from information_schema -----------------------------------

interface ActualColumn {
  name: string;
  type: string;
  notNull: boolean;
  columnDefault: string | null;
}

const ACTUAL_SQL = `
  SELECT c.table_name,
         c.column_name,
         c.data_type,
         c.udt_name,
         c.numeric_precision,
         c.numeric_scale,
         c.character_maximum_length,
         c.datetime_precision,
         c.is_nullable,
         c.column_default
  FROM information_schema.columns c
  JOIN information_schema.tables t
    ON t.table_schema = c.table_schema AND t.table_name = c.table_name
  WHERE c.table_schema = 'public' AND t.table_type = 'BASE TABLE'
  ORDER BY c.table_name, c.ordinal_position`;

function actualTypeString(row: any): string {
  const dataType: string = row.data_type;
  if (dataType === "ARRAY") {
    // udt_name is "_text" for text[]
    return `${String(row.udt_name).replace(/^_/, "")}[]`;
  }
  if (dataType === "numeric" && row.numeric_precision !== null) {
    return `numeric(${row.numeric_precision},${row.numeric_scale ?? 0})`;
  }
  if (dataType === "character varying" && row.character_maximum_length !== null) {
    return `character varying(${row.character_maximum_length})`;
  }
  return dataType;
}

async function readActual(client: pg.Client): Promise<Map<string, Map<string, ActualColumn>>> {
  const { rows } = await client.query(ACTUAL_SQL);
  const out = new Map<string, Map<string, ActualColumn>>();
  for (const row of rows) {
    if (!out.has(row.table_name)) out.set(row.table_name, new Map());
    out.get(row.table_name)!.set(row.column_name, {
      name: row.column_name,
      type: actualTypeString(row),
      notNull: row.is_nullable === "NO",
      columnDefault: row.column_default,
    });
  }
  return out;
}

// --- main --------------------------------------------------------------------

async function main() {
  const { url, scratchUrl } = maintenanceUrl();
  const scratchName = `taptpay_scratch_${crypto.randomBytes(5).toString("hex")}`;

  const admin = new pg.Client({ connectionString: url, application_name: "taptpay-rebuild-gate" });
  admin.on("error", () => undefined);
  await admin.connect();

  console.log(`scratch database: ${scratchName}`);
  await admin.query(`CREATE DATABASE ${scratchName}`);

  let exitCode = 0;
  try {
    const target = new pg.Client({
      connectionString: scratchUrl(scratchName),
      application_name: "taptpay-rebuild-gate",
    });
    target.on("error", () => undefined);
    await target.connect();
    try {
      const dbName = (await target.query("SELECT current_database() AS db")).rows[0].db;
      if (dbName !== scratchName) throw new Error(`connected to ${dbName}, expected ${scratchName}`);

      const result = await runPendingMigrations(target as unknown as MigrationClient, {
        dir: MIGRATIONS_DIR,
        log: (m) => console.log(`   ${m}`),
      });
      console.log(`applied ${result.appliedNow.length} migration(s) to ${scratchName}`);

      const expected = expectedTables();
      const actual = await readActual(target);

      const missingTables: string[] = [];
      const extraTables: string[] = [];
      const missingColumns: string[] = [];
      const extraColumns: string[] = [];
      const typeMismatches: string[] = [];
      const nullabilityMismatches: string[] = [];

      for (const [table, cols] of [...expected].sort()) {
        const have = actual.get(table);
        if (!have) {
          missingTables.push(table);
          continue;
        }
        for (const [name, want] of cols) {
          const got = have.get(name);
          if (!got) {
            missingColumns.push(`${table}.${name}`);
            continue;
          }
          const wantType = normaliseType(want.sqlType);
          const gotType = normaliseType(got.type);
          if (wantType !== gotType) {
            typeMismatches.push(`${table}.${name}: schema.ts ${wantType} vs built ${gotType}`);
          }
          const wantNotNull = want.notNull || want.isPrimaryKey;
          if (wantNotNull !== got.notNull) {
            nullabilityMismatches.push(
              `${table}.${name}: schema.ts ${wantNotNull ? "NOT NULL" : "nullable"} vs built ${got.notNull ? "NOT NULL" : "nullable"}`,
            );
          }
        }
        for (const name of have.keys()) {
          if (!cols.has(name)) extraColumns.push(`${table}.${name}`);
        }
      }
      for (const table of actual.keys()) {
        if (!expected.has(table)) extraTables.push(table);
      }

      const report = (label: string, items: string[]) => {
        console.log(`\n${label}: ${items.length}`);
        for (const item of items.sort()) console.log(`   - ${item}`);
      };

      console.log(`\nschema.ts tables: ${expected.size} | built tables: ${actual.size}`);
      report("TABLES in schema.ts, absent from the built database", missingTables);
      report("COLUMNS in schema.ts, absent from the built database", missingColumns);
      report("TABLES in the built database, absent from schema.ts", extraTables);
      report("COLUMNS in the built database, absent from schema.ts", extraColumns);
      report("TYPE mismatches", typeMismatches);
      report("NULLABILITY mismatches", nullabilityMismatches);

      const drift = missingTables.length + missingColumns.length;
      console.log(`\nDRIFT -> tables: ${missingTables.length}  columns: ${missingColumns.length}`);
      if (drift !== 0) exitCode = 1;
      if (typeMismatches.length + nullabilityMismatches.length > 0) exitCode = 1;
    } finally {
      await target.end().catch(() => undefined);
    }
  } finally {
    // Drop, then prove the drop.
    await admin.query(
      `SELECT pg_terminate_backend(pid) FROM pg_stat_activity WHERE datname = $1 AND pid <> pg_backend_pid()`,
      [scratchName],
    );
    await admin.query(`DROP DATABASE IF EXISTS ${scratchName}`);
    const still = await admin.query(`SELECT 1 FROM pg_database WHERE datname = $1`, [scratchName]);
    if (still.rowCount === 0) {
      console.log(`\nscratch database ${scratchName} DROPPED (verified absent from pg_database)`);
    } else {
      console.error(`\nFAILED TO DROP scratch database ${scratchName}`);
      exitCode = 1;
    }
    const remaining = await admin.query(
      `SELECT datname FROM pg_database WHERE datname LIKE 'taptpay_scratch_%' ORDER BY 1`,
    );
    console.log(
      `remaining taptpay_scratch_* databases: ${remaining.rowCount === 0 ? "none" : remaining.rows.map((r) => r.datname).join(", ")}`,
    );
    await admin.end().catch(() => undefined);
  }

  process.exit(exitCode);
}

main().catch((error) => {
  console.error(error);
  process.exit(1);
});

